// Author: MiYu. Shared terrain blight mutations update query pathing and only the affected render regions.
#include "world.h"
#include "slk.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
namespace {
float number(jass::Real value){float result=std::bit_cast<float>(value.bits());if(!std::isfinite(result))throw std::runtime_error("Non-finite blight coordinate");return result;}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
std::uint64_t mix(std::uint64_t value){value+=0x9e3779b97f4a7c15ull;value=(value^(value>>30))*0xbf58476d1ce4e5b9ull;value=(value^(value>>27))*0x94d049bb133111ebull;return value^(value>>31);}
}
std::optional<size_t> World::terrainCorner(WorldPoint point) const {auto& t=data_.terrain;float x=number(point.x)-t.origin[0],y=number(point.y)-t.origin[1];if(x<0 || y<0 || x>(t.width-1)*128.f || y>(t.height-1)*128.f)return {};unsigned cx=std::min(t.width-1,unsigned(std::floor(x/128+.5f))),cy=std::min(t.height-1,unsigned(std::floor(y/128+.5f)));return size_t(cy)*t.width+cx;}
std::uint32_t World::terrainType(WorldPoint point) const {auto corner=terrainCorner(point);if(!corner)return 0;unsigned slot=terrainSlot(*corner);if(slot>=terrainTypes_.size())throw std::runtime_error("Terrain query outside source tileset");auto raw=terrainTypes_[slot];return ((raw&255)<<24)|((raw&0xff00)<<8)|((raw>>8)&0xff00)|(raw>>24);}
unsigned World::terrainVariation(WorldPoint point) const {auto corner=terrainCorner(point);return corner?data_.terrain.corners[*corner].variation&31:0;}
std::string World::terrainTextureForType(std::uint32_t raw) const {
    if(!terrainTextureIndex_){auto table=SourceTable::read(resources(),"TerrainArt\\Terrain.slk");std::map<std::uint32_t,std::string> index;for(auto& row:table.rows()){auto id=row.find(table.idColumn()),dir=row.find("dir"),file=row.find("file");if(id==row.end() || dir==row.end() || file==row.end() || id->second.size()!=4 || dir->second.empty() || file->second.empty())continue;std::uint32_t key=0;for(unsigned i=0;i<4;++i)key|=std::uint32_t(static_cast<unsigned char>(id->second[i]))<<(i*8);index.try_emplace(key,dir->second+"\\"+file->second+".blp");}terrainTextureIndex_=std::move(index);}
    auto found=terrainTextureIndex_->find(raw);if(found==terrainTextureIndex_->end())throw std::runtime_error("Unknown source terrain type");if(!resources().readTexture(found->second))throw std::runtime_error("Missing source terrain texture: "+found->second);return found->second;
}
const std::string& World::terrainTexture(unsigned slot) const {if(slot>=terrainTypes_.size())throw std::runtime_error("Terrain texture slot outside supported range");auto& path=terrainTextures_.at(slot);if(path.empty())path=terrainTextureForType(terrainTypes_[slot]);return path;}
void World::setTerrainType(WorldPoint point,std::uint32_t type,int variation,int area,int shape,const std::function<std::uint32_t()>& random) {
    auto center=terrainCorner(point);if(!center)return;if(area<1 || area>256 || (shape!=0 && shape!=1) || variation < -1 || variation>31)throw std::runtime_error("Unsupported terrain type area, shape or variation");auto& t=data_.terrain;auto raw=((type&255)<<24)|((type&0xff00)<<8)|((type>>8)&0xff00)|(type>>24);auto at=std::find(terrainTypes_.begin(),terrainTypes_.end(),raw);unsigned slot;if(at==terrainTypes_.end()){if(terrainTypes_.size()>=256)throw std::runtime_error("Extended terrain type budget exceeded");auto path=terrainTextureForType(raw);slot=unsigned(terrainTypes_.size());terrainTypes_.push_back(raw);terrainTextures_.push_back(std::move(path));}else slot=unsigned(at-terrainTypes_.begin());int cx=int(*center%t.width),cy=int(*center/t.width),start=-(area/2),end=start+area;unsigned columns=(t.width-2)/16+1;bool changed=false;
    for(int dy=start;dy<end;++dy)for(int dx=start;dx<end;++dx){int x=cx+dx,y=cy+dy;if(x<0 || y<0 || x>=int(t.width) || y>=int(t.height))continue;if(shape==0){double ox=double(dx)-(area%2?0.0:-.5),oy=double(dy)-(area%2?0.0:-.5),radius=std::max(.5,double(area)/2);if(ox*ox+oy*oy>radius*radius)continue;}auto index=size_t(y)*t.width+x;auto& corner=t.corners[index];unsigned value=variation<0?(random()%16):unsigned(variation);auto nextVariation=std::uint8_t((corner.variation&0xe0)|value);if(terrainSlots_[index]==slot && corner.variation==nextVariation)continue;if(!changed){++terrainRevision_;++blightRevision_;changed=true;}terrainSlots_[index]=std::uint16_t(slot);if(slot<16)corner.flags=std::uint8_t((corner.flags&0xf0)|slot);corner.variation=nextVariation;for(unsigned py=y?unsigned(y)-1:0;py<=std::min(unsigned(y),t.height-2);++py)for(unsigned px=x?unsigned(x)-1:0;px<=std::min(unsigned(x),t.width-2);++px)terrainChunks_[size_t(py/16)*columns+px/16]=terrainRevision_;dirtyBlight(unsigned(x),unsigned(y));}
}
void World::updateBlightFingerprint(size_t index,bool corner,bool add) {auto key=std::uint64_t(index)^(corner?0x8f4a83d9c2e16b07ull:0x1a68e5b4d709c32full);blightFingerprint_[0]^=mix(key);auto value=mix(key^0xd7b195c6a3248e0full);if(add)blightFingerprint_[1]+=value;else blightFingerprint_[1]-=value;}
void World::initializeBlightFingerprint() {auto& t=data_.terrain;unsigned width=data_.pathing?data_.pathing->width:(t.width-1)*4,height=data_.pathing?data_.pathing->height:(t.height-1)*4;blightFingerprint_={mix((std::uint64_t(width)<<32)|height),mix((std::uint64_t(t.width)<<32)|t.height)};auto& cells=data_.pathing?data_.pathing->cells:blightPathing_;for(size_t i=0;i<cells.size();++i)if(cells[i]&0x20)updateBlightFingerprint(i,false,true);for(size_t i=0;i<t.corners.size();++i)if(t.corners[i].flags&0x20)updateBlightFingerprint(i,true,true);}
bool World::blighted(WorldPoint point) const {
    auto& terrain=data_.terrain;float x=number(point.x)-terrain.origin[0],y=number(point.y)-terrain.origin[1];unsigned width=data_.pathing?data_.pathing->width:(terrain.width-1)*4,height=data_.pathing?data_.pathing->height:(terrain.height-1)*4;if(x<0 || y<0 || x>=width*32.f || y>=height*32.f)return false;auto& cells=data_.pathing?data_.pathing->cells:blightPathing_;return (cells[size_t(std::floor(y/32))*width+size_t(std::floor(x/32))]&0x20)!=0;
}
void World::dirtyBlight(unsigned x,unsigned y) {
    auto& t=data_.terrain;unsigned columns=(t.width-2)/16+1;for(unsigned cy=y?y-1:0;cy<=std::min(y,t.height-2);++cy)for(unsigned cx=x?x-1:0;cx<=std::min(x,t.width-2);++cx)blightChunks_[size_t(cy/16)*columns+cx/16]=blightRevision_;
}
void World::changeBlight(WorldRect rectangle,std::optional<WorldPoint> center,float radius,bool add) {
    auto& t=data_.terrain;float x0=number(rectangle.minX),y0=number(rectangle.minY),x1=number(rectangle.maxX),y1=number(rectangle.maxY);if(x0>x1)std::swap(x0,x1);if(y0>y1)std::swap(y0,y1);float cx=center?number(center->x):0,cy=center?number(center->y):0;auto inside=[&](float x,float y){return x>=x0 && x<=x1 && y>=y0 && y<=y1 && (!center || (double(x)-cx)*(double(x)-cx)+(double(y)-cy)*(double(y)-cy)<=double(radius)*radius);};
    auto range=[](float first,float last,float origin,unsigned count,float step,float offset){double low=(double(first)-origin-offset)/step,high=(double(last)-origin-offset)/step;return std::pair{int(std::clamp(std::ceil(low),0.,double(count))),int(std::clamp(std::floor(high)+1,0.,double(count)))};};unsigned width=data_.pathing?data_.pathing->width:(t.width-1)*4,height=data_.pathing?data_.pathing->height:(t.height-1)*4;auto& pathing=data_.pathing?data_.pathing->cells:blightPathing_;auto [left,right]=range(x0,x1,t.origin[0],width,32,16);auto [bottom,top]=range(y0,y1,t.origin[1],height,32,16);bool changed=false;
    for(int y=bottom;y<top;++y)for(int x=left;x<right;++x)if(inside(t.origin[0]+x*32+16,t.origin[1]+y*32+16)){auto index=size_t(y)*width+x;auto& value=pathing[index];auto next=std::uint8_t(add?value|0x20:value&~0x20);if(next!=value){value=next;updateBlightFingerprint(index,false,add);changed=true;}}
    auto [cornerLeft,cornerRight]=range(x0,x1,t.origin[0],t.width,128,0);auto [cornerBottom,cornerTop]=range(y0,y1,t.origin[1],t.height,128,0);bool revised=false;
    for(int y=cornerBottom;y<cornerTop;++y)for(int x=cornerLeft;x<cornerRight;++x)if(inside(t.origin[0]+x*128,t.origin[1]+y*128)){auto index=size_t(y)*t.width+x;auto& value=t.corners[index].flags;auto next=std::uint8_t(add?value|0x20:value&~0x20);if(next!=value){if(!revised){++blightRevision_;revised=true;}value=next;updateBlightFingerprint(index,true,add);dirtyBlight(unsigned(x),unsigned(y));}}
    if(changed && !revised)++blightRevision_;
}
void World::blight(WorldRect rectangle,bool add) {changeBlight(rectangle,{},0,add);}
void World::blight(WorldPoint center,float radius,bool add) {if(!std::isfinite(radius) || radius<0 || radius>10000000)throw std::runtime_error("Blight radius outside supported range");float x=number(center.x),y=number(center.y);changeBlight({real(x-radius),real(y-radius),real(x+radius),real(y+radius)},center,radius,add);}
void World::blightPoint(WorldPoint point,bool add) {auto& t=data_.terrain;float x=t.origin[0]+std::floor((number(point.x)-t.origin[0])/128)*128,y=t.origin[1]+std::floor((number(point.y)-t.origin[1])/128)*128;changeBlight({real(x),real(y),real(x+128),real(y+128)},{},0,add);}
}
